create type public.user_role as enum ('user', 'admin');
create type public.replay_status as enum ('created', 'running', 'paused', 'completed');
create type public.backtest_status as enum ('queued', 'running', 'completed', 'failed');
create type public.order_side as enum ('buy', 'sell');
create type public.order_type as enum ('market', 'limit');
create type public.order_status as enum ('submitted', 'filled', 'cancelled');
create type public.provider_status as enum ('healthy', 'degraded', 'offline');

create table public."users" (
  "id" integer generated by default as identity primary key,
  "openId" varchar(64) not null unique,
  "name" text,
  "email" varchar(320),
  "loginMethod" varchar(64),
  "role" public.user_role not null default 'user',
  "createdAt" timestamp not null default now(),
  "updatedAt" timestamp not null default now(),
  "lastSignedIn" timestamp not null default now()
);
create table public."watchlists" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "name" varchar(120) not null, "columns" text not null, "createdAt" timestamp not null default now(), "updatedAt" timestamp not null default now()
);
create index "watchlists_userId_idx" on public."watchlists" ("userId");
create table public."watchlistItems" (
  "id" integer generated by default as identity primary key, "watchlistId" integer not null, "symbol" varchar(16) not null, "sortOrder" integer not null default 0, "alertsMuted" integer not null default 0, "createdAt" timestamp not null default now()
);
create index "watchlistItems_watchlistId_idx" on public."watchlistItems" ("watchlistId");
create table public."scannerPresets" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "name" varchar(120) not null, "scanner" varchar(80) not null, "thresholds" text not null, "createdAt" timestamp not null default now(), "updatedAt" timestamp not null default now()
);
create table public."alertRules" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "name" varchar(120) not null, "symbol" varchar(16), "condition" text not null, "enabled" integer not null default 1, "createdAt" timestamp not null default now()
);
create table public."workspaceLayouts" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "name" varchar(120) not null, "layout" text not null, "createdAt" timestamp not null default now(), "updatedAt" timestamp not null default now()
);
create table public."replaySessions" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "symbol" varchar(16) not null, "startAt" timestamp not null, "endAt" timestamp not null, "speed" numeric(8,2) not null default 1, "status" public.replay_status not null default 'created', "createdAt" timestamp not null default now()
);
create table public."backtestRuns" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "name" varchar(120) not null, "strategy" text not null, "metrics" text not null, "status" public.backtest_status not null default 'queued', "createdAt" timestamp not null default now()
);
create index "backtestRuns_userId_idx" on public."backtestRuns" ("userId");
create table public."paperOrders" (
  "id" integer generated by default as identity primary key, "userId" integer not null, "idempotencyKey" varchar(80) unique, "symbol" varchar(16) not null, "side" public.order_side not null, "quantity" numeric(18,4) not null, "orderType" public.order_type not null default 'market', "limitPrice" numeric(18,4), "fillPrice" numeric(18,4), "status" public.order_status not null default 'submitted', "createdAt" timestamp not null default now()
);
create index "paperOrders_userId_idx" on public."paperOrders" ("userId");
create index "paperOrders_symbol_idx" on public."paperOrders" ("symbol");
create table public."auditEvents" (
  "id" integer generated by default as identity primary key, "userId" integer, "action" varchar(80) not null, "resource" varchar(120) not null, "metadata" text not null, "requestId" varchar(80), "createdAt" timestamp not null default now()
);
create table public."providerHealth" (
  "id" integer generated by default as identity primary key, "provider" varchar(40) not null unique, "status" public.provider_status not null default 'offline', "lastSuccessAt" timestamp, "lastFailureAt" timestamp, "lastError" text, "latencyMs" integer, "updatedAt" timestamp not null default now()
);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new."updatedAt" = now(); return new; end; $$;
create trigger users_set_updated_at before update on public."users" for each row execute function public.set_updated_at();
create trigger watchlists_set_updated_at before update on public."watchlists" for each row execute function public.set_updated_at();
create trigger scanner_presets_set_updated_at before update on public."scannerPresets" for each row execute function public.set_updated_at();
create trigger workspace_layouts_set_updated_at before update on public."workspaceLayouts" for each row execute function public.set_updated_at();
create trigger provider_health_set_updated_at before update on public."providerHealth" for each row execute function public.set_updated_at();

alter table public."users" enable row level security;
alter table public."watchlists" enable row level security;
alter table public."watchlistItems" enable row level security;
alter table public."scannerPresets" enable row level security;
alter table public."alertRules" enable row level security;
alter table public."workspaceLayouts" enable row level security;
alter table public."replaySessions" enable row level security;
alter table public."backtestRuns" enable row level security;
alter table public."paperOrders" enable row level security;
alter table public."auditEvents" enable row level security;
alter table public."providerHealth" enable row level security;
